class Fraction
  attr_reader :numerator, :denominator

  def initialize(numerator, denominator)
    @numerator = numerator
    @denominator = denominator
  end

  def +(other)
    if other.is_a?(Integer)
      Fraction.new(@numerator + other * @denominator, @denominator)
    elsif other.is_a?(Fraction)
      lcm = @denominator.lcm(other.denominator)
      Fraction.new(
        @numerator * (lcm / @denominator) + other.numerator * (lcm / other.denominator),
        lcm
      )
    else
      raise TypeError, "Unsupported operand type for +"
    end
  end

  def ==(other)
    other.is_a?(Fraction) && @numerator == other.numerator && @denominator == other.denominator
  end
end
